INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(50411, 'Joshua 22:12', 'Joshua', 22, 12, 'نو د لوېدیځو قبیلو ټول خلک په شیلوه کې سره راټول شول چې لاړ شي او د ختیځو قبیلو سره وجنګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_12.mp3', '', 1761754199, 1761754199),
(50412, 'Joshua 22:13', 'Joshua', 22, 13, 'نو د اسراییلو خلکو د العازار کاهن زوی فینحاس د جلعاد خاورې ته د روبین، جاد او د ختیځې منسي قبیلو ته ولېږه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_13.mp3', '', 1761754199, 1761754199),
(50413, 'Joshua 22:14', 'Joshua', 22, 14, 'نو د فینحاس سره لس مشران لاړل، د هرې لوېدیځې قبیلې څخه یو یو کس یعنې د هغوی د کورنیو د مشرانو څخه یو یو کس.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_14.mp3', '', 1761754199, 1761754199),
(50414, 'Joshua 22:15', 'Joshua', 22, 15, 'کله چې هغوی د جلعاد خاورې ته د روبین، جاد او ختیځې منسي خلکو ته ورغلل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_15.mp3', '', 1761754199, 1761754199),
(50415, 'Joshua 22:16', 'Joshua', 22, 16, 'هغوی وویل: «مونږ د څښتن د ټول قوم له خوا خبرې کوو: ‹تاسو ولې د اسراییلو د څښتن خدای په وړاندې داسې بد کار کړی دی؟ تاسو د خپلو ځانونو دپاره د دې قربانۍ د ځای په جوړولو سره د هغه په وړاندې سرکښي کړې ده! تاسو نور د هغه پیروان نه یئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_16.mp3', '', 1761754199, 1761754199),
(50416, 'Joshua 22:17', 'Joshua', 22, 17, 'په فغور کې زمونږ ګناه در په یاده کړئ. ایا زمونږ دپاره هغه بس نه وه؟ سره له دې چې د څښتن په قوم باندې وبا نازله شوه، خو تر نن ورځې پورې مونږ د هغې ګناه څخه خپل ځانونه پاک کړي نه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_17.mp3', '', 1761754199, 1761754199),
(50417, 'Joshua 22:18', 'Joshua', 22, 18, 'ایا تاسو اوس غواړئ چې د څښتن د پیروۍ څخه انکار وکړئ؟ که چېرې تاسو نن د څښتن په وړاندې سرکښي وکړئ، سبا به هغه د اسراییلو په ټول قوم باندې په قهر شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_18.mp3', '', 1761754199, 1761754199),
(50418, 'Joshua 22:19', 'Joshua', 22, 19, 'خو که چېرې ستاسو خاوره د عبادت دپاره مناسبه نه وي، نو د څښتن ځمکې ته راشئ چې د هغه سپېڅلې خېمه په کې ولاړه ده او زمونږ په منځ کې ځمکه واخلئ. خو د څښتن په وړاندې سرکښي مه کوئ او پرته زمونږ د څښتن خدای د قربانۍ د ځای څخه د بلې قربانۍ د ځای په جوړولو سره مونږ مه ګناهکاروئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_19.mp3', '', 1761754199, 1761754199),
(50419, 'Joshua 22:20', 'Joshua', 22, 20, 'ایا هغه څه چې د عخان سره وشول هغه مو په یاد دي؟ څښتن مونږ ته ویلي وو چې د اریحا د ښار ټول شیان له منځه یوسئ، خو عخان د څښتن د حکم څخه سرغړونه وکړه او څښتن مونږ ټولو ته سزا راکړه. عخان د خپلو کړو له امله مړ شو او نور ډېر اسراییلیان هم د عخان د ګناه له امله مړه شول.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_20.mp3', '', 1761754199, 1761754199),
(50420, 'Joshua 22:21', 'Joshua', 22, 21, 'د روبین، جاد او ختیځې منسي د قبیلو خلکو د لوېدیځو قبیلو استازو ته په ځواب کې وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_21.mp3', '', 1761754199, 1761754199),
(50421, 'Joshua 22:22', 'Joshua', 22, 22, '«څښتن یوازېنی قوي خدای دی! مونږ د هغه څخه غوښتنه کوو چې زمونږ شاهد اوسي! هغه پوهیږي چې مونږ ولې داسې کار کړی دی او مونږ غواړو چې تاسو هم ورباندې پوه شئ! که چېرې مونږ د څښتن په وړاندې سرکښي کړې وي او د هغه سره مو خپل لوظ مات کړی وي، نو څښتن دې نور مونږ ژوندي نه پرېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_22.mp3', '', 1761754199, 1761754199),
(50422, 'Joshua 22:23', 'Joshua', 22, 23, 'که چېرې مونږ د څښتن څخه پیروي کول پرې ایښي وي او خپل د قربانۍ ځای مو جوړ کړی وي چې په هغې باندې سوځېدونکې نذرانې یا د غلو دانو یا د سلامتۍ نذرانې وړاندې کړو، نو پرېږدئ چې څښتن په خپله مونږ ته سزا راکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_23.mp3', '', 1761754199, 1761754199),
(50423, 'Joshua 22:24', 'Joshua', 22, 24, 'نه! مونږ د دې وېرې له امله دا کار وکړ چې کېدای شي یوه ورځ ستاسو اولاده زمونږ اولادې ته ووایي چې تاسو څه حق لرئ چې د اسراییلو د څښتن خدای عبادت کوئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_24.mp3', '', 1761754199, 1761754199),
(50424, 'Joshua 22:25', 'Joshua', 22, 25, 'څښتن د اردن د سیند څخه زمونږ او ستاسو یعنې د روبین او جاد د خلکو ترمنځ یو سرحد جوړ کړ. تاسو د څښتن سره هېڅ کار نه لرئ. بیا کېدای شي چې ستاسو اولاده زمونږ اولاده د څښتن د عبادت څخه منع کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_25.mp3', '', 1761754199, 1761754199),
(50425, 'Joshua 22:26', 'Joshua', 22, 26, 'نو مونږ د قربانۍ د ځای د جوړولو پرېکړه وکړه، نه د سوځېدونکو نذرانو دپاره او نه د قربانیو دپاره،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_26.mp3', '', 1761754199, 1761754199),
(50426, 'Joshua 22:27', 'Joshua', 22, 27, 'بلکې دا به زمونږ او ستاسو د خلکو دپاره او زمونږ څخه وروسته نسلونو دپاره یوه نښه وي چې مونږ به د څښتن د سپېڅلې خېمې په مخکې د سوځېدونکو نذرانو، قربانیو او سلامتۍ د نذرانو په وړاندې کولو سره د هغه عبادت کوو. بیا به په راتلونکې کې ستاسو اولاده نه شي کولای چې زمونږ اولادې ته داسې ووایي چې تاسو د څښتن عبادت نه شئ کولای.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_27.mp3', '', 1761754199, 1761754199),
(50427, 'Joshua 22:28', 'Joshua', 22, 28, 'مونږ فکر کاوه چې که چېرې داسې وشي، امکان لري چې زمونږ اولاده ووایي چې ګورئ، زمونږ نیکونو د څښتن د قربانۍ د ځای په شان یوه نمونه جوړه کړه. دا د سوځېدونکو نذرانو یا د قربانیو دپاره نه، بلکې هغه یې د دې دپاره جوړه کړې ده چې دا وښایي چې مونږ هم ستاسو په شان د څښتن خلک یو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_28.mp3', '', 1761754199, 1761754199),
(50428, 'Joshua 22:29', 'Joshua', 22, 29, 'مونږ به په یقین سره د څښتن په وړاندې سرکښي ونه کړو او نه به د قربانۍ د ځای په جوړولو سره چې په هغه باندې سوځېدونکې نذرانې یا د غلو دانو نذرانې یا قربانۍ وړاندې کړو، د هغه پیروي کول پرېږدو. مونږ به بل داسې د قربانۍ ځای جوړ نه کړو چې زمونږ د څښتن خدای د قربانګاه ځای ونیسي چې د هغه د سپېڅلې خېمې په مخکې ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_29.mp3', '', 1761754199, 1761754199),
(50429, 'Joshua 22:30', 'Joshua', 22, 30, 'فینحاس کاهن او د لوېدیځو قبیلو لسو مشرانو چې د هغه سره وو د روبین، جاد او ختیځې منسي د قبیلو د خلکو خبرې واورېدلې او هغوی قانع شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_30.mp3', '', 1761754199, 1761754199),
(50430, 'Joshua 22:31', 'Joshua', 22, 31, 'فینحاس هغوی ته وویل: «اوس مونږ په دې پوه شو چې څښتن زمونږ سره مل دی. تاسو د هغه په وړاندې سرکښي نه ده کړې بلکې د اسراییلو قوم مو د څښتن د سزا څخه ژغورلی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_31.mp3', '', 1761754199, 1761754199),
(50431, 'Joshua 22:32', 'Joshua', 22, 32, 'بیا فینحاس او د لوېدیځو قبیلو مشران بېرته د کنعان خاورې ته راستانه شول او څه چې پېښ شوي وو هغه یې د اسراییلو خلکو ته بیان کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_32.mp3', '', 1761754199, 1761754199),
(50432, 'Joshua 22:33', 'Joshua', 22, 33, 'اسراییلیان قانع شول او د خدای ستاینه یې وکړه. هغوی نور داسې خبرې نه کولې چې د روبین او جاد د خلکو سره جنګ وکړي او د هغوی خاوره له منځه یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_33.mp3', '', 1761754199, 1761754199),
(50433, 'Joshua 22:34', 'Joshua', 22, 34, 'د روبین او جاد خلکو وویل: «دا د قربانۍ ځای زمونږ د ټولو ترمنځ شاهد دی چې څښتن زمونږ خدای دی.» نو هغه د قربانۍ ځای یې د شاهد په نوم یاد کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_34.mp3', '', 1761754199, 1761754199),
(50434, 'Psalms 41:1', 'Psalms', 41, 1, 'بختور دی هغه څوک چې کوي فکر د غریبو په هکله د سختۍ وخت کې ورکوي څښتن خلاصون ده ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms41_verse_1.mp3', '', 1761754199, 1761754199),
(50435, 'Psalms 41:2', 'Psalms', 41, 2, 'څښتن به وکاندي ساتنه د ده او وبه یې ساتي ژوندی برکتي به کړي دا خپل وطن کې دا به پرېنږدي چې دې خپل دښمن ته لاس ته ورشي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms41_verse_2.mp3', '', 1761754199, 1761754199),
(50436, 'Psalms 41:3', 'Psalms', 41, 3, 'د ناروغۍ وخت کې څښتن به مرسته وکاندي له ده سره او د ده صحت به بېرته روغ کاندي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms41_verse_3.mp3', '', 1761754199, 1761754199),
(50437, 'Psalms 41:4', 'Psalms', 41, 4, 'ما وویل: «څښتنه، ما باندې رحم وکړه راکړه شفا ستا مقابل کې مې ګناه کړې ده»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms41_verse_4.mp3', '', 1761754199, 1761754199),
(50438, 'Psalms 41:5', 'Psalms', 41, 5, 'بدې خبرې دښمنان مې کړي زما په هکله وایي چې «کله به مړ کیږي چې یې نوم ورک شي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms41_verse_5.mp3', '', 1761754199, 1761754199),
(50439, 'Psalms 41:6', 'Psalms', 41, 6, 'څوک چې کتلو ته راځي زما هغوی نه دي اخلاصمن خلک راټولوي زما په هکله هغوی بد خبرونه بیا بهر وځي او هرچا ته دا خبرې کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms41_verse_6.mp3', '', 1761754199, 1761754199),
(50440, 'Psalms 41:7', 'Psalms', 41, 7, 'ټول دښمنان مې پس پسی کوي په خپل منځ کې زما په هکله دوی جوړوي پلان چې راته ورسوي زیان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms41_verse_7.mp3', '', 1761754199, 1761754199),
(50441, 'Psalms 41:8', 'Psalms', 41, 8, 'وایي هغوی چې «دی اخته دی په وژونکي مرض بیا به پورته نه شي له خپل ځای ځینې»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms41_verse_8.mp3', '', 1761754199, 1761754199),
(50442, 'Psalms 41:9', 'Psalms', 41, 9, 'حتی تر دې په نژدې دوست چې ډېر اعتبار مې کاوه هغه چې زما سره ډوډۍ خوړله هغه زما په ضد راپورته شولو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms41_verse_9.mp3', '', 1761754199, 1761754199),
(50443, 'Psalms 41:10', 'Psalms', 41, 10, 'ای څښتنه، رحم وکړه په ما باندې او ماته بېرته ښه صحت راکړه نو زه به واخلمه بدل له دښمنانو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms41_verse_10.mp3', '', 1761754199, 1761754199),
(50444, 'Psalms 41:11', 'Psalms', 41, 11, 'زه پوهېږم چې خوشحاله یې له ما نه ځکه چې نه مومي دښمن بری په ما باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms41_verse_11.mp3', '', 1761754199, 1761754199),
(50445, 'Psalms 41:12', 'Psalms', 41, 12, 'راسره کړی دې کومک ځکه صادق یمه زه په خپل حضور کې مې ساتې ته تر ابده پورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms41_verse_12.mp3', '', 1761754199, 1761754199),
(50446, 'Psalms 41:13', 'Psalms', 41, 13, 'ثنا او صفت دې وي د اسراییلو څښتن خدای ته وکړئ ثنا او صفت یې د ازل نه تر ابده پورې امین! امین!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms41_verse_13.mp3', '', 1761754199, 1761754199),
(50447, 'Joshua 15:1', 'Joshua', 15, 1, 'د یهودا د قبیلې طایفو د ځمکې یوه برخه تر لاسه کړه چې په لاندې ډول تشریح کیږي. دا ځمکه د صین د دښتې جنوب یعنې د ادوم د پولې پورې رسېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_1.mp3', '', 1761754199, 1761754199),
(50448, 'Joshua 15:2', 'Joshua', 15, 2, 'دا جنوبي پوله د مړې بحیرې د جنوبي برخې په پای کې پیل شوې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_2.mp3', '', 1761754199, 1761754199),
(50449, 'Joshua 15:3', 'Joshua', 15, 3, 'د عقربیم د غاښي جنوب خواته تللې، د صین تر دښتې پورې غزېدلې ده او د قادش برنیع تر جنوب پورې وه. بیا هغه د حزرون څخه تېره شوې، پورته د ادار خواته تللې او د قرقع خواته ګرځېدلې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_3.mp3', '', 1761754199, 1761754199),
(50450, 'Joshua 15:4', 'Joshua', 15, 4, 'هغه د عصمون څخه تېره شوې او د هغه خوړ سره یوځای شوې ده چې د مصر د پولې سره ؤ او د مدیترانې په بحیره کې ختمه شوې ده. دا د ټولو اسراییلو جنوبي پوله هم وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_4.mp3', '', 1761754199, 1761754199),
(50451, 'Joshua 15:5', 'Joshua', 15, 5, 'د یهودا د قبیلې ختیځه پوله مړه بحیره وه. دا پوله په شمال کې تر هغه ځای پورې غزېدلې ده په کوم ځای کې چې د اردن سیند د مړې بحیرې سره یوځای کیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_5.mp3', '', 1761754199, 1761754199),
(50452, 'Joshua 15:6', 'Joshua', 15, 6, 'او هغه تر بیت حجله پورې غزېدلې ده، د بیت عربه شمال خواته تللې او د هغه ځای څخه د بوهن ګټ ته راوتلې ده. (بوهن د روبین زوی ؤ.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_6.mp3', '', 1761754199, 1761754199),
(50453, 'Joshua 15:7', 'Joshua', 15, 7, 'او دا پوله بیا د مصیبت له درې څخه پورته دبیر ته راوتلې او د شمال خواته د جلجال په لوري چې د درې په جنوب کې د ادومیم غاښي ته مخامخ ده، ګرځېدلې ده. بیا هغه د عین شمس د چینو خواته تللې او په عین روجل کې راوتلې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_7.mp3', '', 1761754199, 1761754199),
(50454, 'Joshua 15:8', 'Joshua', 15, 8, 'بیا دا پوله د غونډۍ جنوب خواته د هنوم د زوی د درې په لاره تېره شوې ده چېرته چې د یبوسیانو ښار یعنې اورشلیم پروت ؤ. دا پوله بیا د هغې غونډۍ سرته رسیږي چې د هنوم د درې په لوېدیځه خوا کې وه چې د رفاییم د درې شمالي برخه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_8.mp3', '', 1761754199, 1761754199),
(50455, 'Joshua 15:9', 'Joshua', 15, 9, 'د هغه ځای څخه دا پوله د نفتوح چینې او بیا هغو ښارګوټو ته تللې ده چې د عفرون غر ته نژدې وو. دا پوله هلته د بعله خواته ګرځېدلې ده چې اوس د قریت یعاریم په نوم یادیږي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_9.mp3', '', 1761754199, 1761754199),
(50456, 'Joshua 15:10', 'Joshua', 15, 10, 'چېرته چې دغه پوله د ادوم د غرنۍ سیمې په خوا کې د بعله د لوېدیځ څخه راچاپېره شوې ده. بیا هغه د یعاریم د غره شمالي خوا (کسالون) ته تللې، ښکته بیت شمس ته راوتلې او د تمنه څخه تېریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_10.mp3', '', 1761754199, 1761754199),
(50457, 'Joshua 15:11', 'Joshua', 15, 11, 'بیا دا پوله هغې غونډۍ ته وتلې ده چې د عقرون په شمال کې ده. بیا د شکرون خواته ګرځېدلې، د بعله د غره څخه تېره شوې او یبییل ته راوتلې ده. دا پوله د مدیترانې په بحیره کې ختمه شوې ده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_11.mp3', '', 1761754199, 1761754199),
(50458, 'Joshua 15:12', 'Joshua', 15, 12, 'او هلته یې لوېدیځه پوله جوړه کړې ده. د یهودا خلک په دې سرحدونو کې اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_12.mp3', '', 1761754199, 1761754199),
(50459, 'Joshua 15:13', 'Joshua', 15, 13, 'څنګه چې څښتن یوشع ته حکم کړی ؤ، د یهودا د سیمې یوه برخه د یفنه زوی کالیب ته چې د یهودا د قبیلې څخه ؤ ورکړل شوه. هغه قریت اربع یعنې د حبرون ښار چې د عناق د نیکه یعنې اربع پورې یې اړه درلودله تر لاسه کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_13.mp3', '', 1761754199, 1761754199),
(50460, 'Joshua 15:14', 'Joshua', 15, 14, 'کالیب د عناق اولاده یعنې د شیشای، اخیمان او تلمای طایفې د ښار څخه وشړلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_14.mp3', '', 1761754199, 1761754199),
(50461, 'Joshua 15:15', 'Joshua', 15, 15, 'کالیب د هغه ځای څخه د دبیر په اوسېدونکو باندې د حملې دپاره لاړ. (دا ښار مخکې د قریت سفر په نوم یادېده.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_15.mp3', '', 1761754199, 1761754199),
(50462, 'Joshua 15:16', 'Joshua', 15, 16, 'کالیب وویل: «هرچا چې قریت سفر فتح کړ، زه به خپله لور عکسه هغه ته په نکاح ورکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_16.mp3', '', 1761754199, 1761754199),
(50463, 'Joshua 15:17', 'Joshua', 15, 17, 'عتني ییل د کالیب د ورور قناز زوی هغه ښار ونیوه، نو کالیب خپله لور هغه ته په نکاح ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_17.mp3', '', 1761754199, 1761754199),
(50464, 'Joshua 15:18', 'Joshua', 15, 18, 'د واده په ورځ عتني ییل هغه وهڅوله چې د خپل پلار څخه یو پټی وغواړي. عکسه د خپل خره څخه ښکته شوه او کالیب د هغې څخه پوښتنه وکړه: «څه غواړې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_18.mp3', '', 1761754199, 1761754199),
(50465, 'Joshua 15:19', 'Joshua', 15, 19, 'هغې په ځواب کې وویل: «زه د اوبو یو څو چینې غواړم. هغه ځمکه چې تا راته راکړې ده هغه په جنوبي دښته کې ده.» نو کالیب هغې ته پورتنۍ او ښکتنۍ چینې ورکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_19.mp3', '', 1761754199, 1761754199),
(50466, 'Joshua 15:20', 'Joshua', 15, 20, 'دا هغه ځمکه ده چې د یهودا د قبیلې طایفو د خپل ملکیت په توګه تر لاسه کړه:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_20.mp3', '', 1761754199, 1761754199),
(50467, 'Joshua 15:21', 'Joshua', 15, 21, 'هغه لېرې جنوبي ښارګوټي چې د هغوی پورې یې اړه درلودله، یعنې هغه ښارګوټي چې د ادوم پولې ته نژدې وو دا وو: قبصییل، عیدر، یاجور،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua15_verse_21.mp3', '', 1761754199, 1761754199),
